-- Generated by drizzle-kit, then reviewed and given the catalog's
-- immutability trigger by hand (BUILD.md P9.3; 0001 explains the trigger).
-- An import's goals group its plan list (catalog/goals.json); each row's
-- plan is one of that import's own plans. The web role reads it, as 0002's
-- default privileges already give; the grant is said plainly here too.
CREATE TABLE "app"."catalog_goals" (
	"import_id" integer NOT NULL,
	"goal" text NOT NULL,
	"position" integer NOT NULL,
	"plan_id" text NOT NULL,
	CONSTRAINT "catalog_goals_import_id_goal_plan_id_pk" PRIMARY KEY("import_id","goal","plan_id"),
	CONSTRAINT "catalog_goals_position" UNIQUE("import_id","goal","position"),
	CONSTRAINT "catalog_goals_position_from_1" CHECK ("app"."catalog_goals"."position" >= 1)
);
--> statement-breakpoint
ALTER TABLE "app"."catalog_goals" ADD CONSTRAINT "catalog_goals_import_id_plan_id_catalog_import_plans_import_id_plan_id_fk" FOREIGN KEY ("import_id","plan_id") REFERENCES "app"."catalog_import_plans"("import_id","plan_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE TRIGGER "catalog_goals_immutable" BEFORE UPDATE OR DELETE ON "app"."catalog_goals"
	FOR EACH ROW EXECUTE FUNCTION "app"."catalog_refuse_change"();--> statement-breakpoint
GRANT SELECT ON "app"."catalog_goals" TO "daybyword_web";
